let tacticsPreview=null,tacticsPreviewContext=null,tacticsBoardFingerprint=null,tacticsBoardOpen=true;
const tacticsNumber=value=>value>0&&value<.05?'<0.1':Number(value.toFixed(1)).toLocaleString('ko-KR');
function tacticsDiagram(d,tactic){
 const layout=F.formationPositions[d.context.formation],own={GK:[[50,88]],...layout};let dots='',counters={GK:0,DEF:0,MID:0,FW:0};
 for(const p of d.lineup){const [px,py]=own[p.pos][counters[p.pos]++],x=12+(100-py)*2.4,y=12+px*2.06;dots+=`<circle cx="${x}" cy="${y}" r="10" fill="#e74755"/><text x="${x}" y="${y+3}" text-anchor="middle" fill="#ffffff" font-size="8" font-weight="700">${p.no}</text>`;}
 const opp=[[355,115],[307,40],[307,90],[307,140],[307,190],[266,42],[275,90],[275,140],[266,188],[200,65],[200,165]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#cbd3de" fill-opacity=".65"/>`).join('');
 const paths={balanced:['M130 90Q164 75 201 90','M130 140Q164 155 201 140'],press:['M148 40L258 40','M130 90L265 90','M130 140L265 140','M148 190L258 190'],counter:['M79 40Q170 4 300 55','M79 190Q170 228 300 175']}[tactic];
 const caption={balanced:'중원에서 간격을 유지하며 기회를 기다립니다.',press:'앞으로 압박합니다. 양 팀의 찬스 지표가 늘어납니다.',counter:'빠른 공격진의 침투를 노립니다. 전체 찬스는 줄어듭니다.'}[tactic];
 return `<figure class="tactics-diagram"><svg viewBox="0 0 380 230" role="img" aria-label="${escapeText(d.context.formation.split('').join('-')+' '+caption+' 전술 개념도')}"><defs><marker id="tactics-arrow" markerWidth="6" markerHeight="6" refX="4" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="#e74755" stroke-width="1.4"/></marker></defs><rect x="1" y="1" width="378" height="228" rx="8" fill="#1d3d34"/><g fill="none" stroke="#90b2a4" stroke-opacity=".4"><rect x="12" y="12" width="356" height="206"/><path d="M190 12V218"/><circle cx="190" cy="115" r="31"/><path d="M12 67H63V163H12M368 67H317V163H368"/></g>${opp}<g fill="none" stroke="#e74755" stroke-width="2.3" stroke-dasharray="5 5" marker-end="url(#tactics-arrow)">${paths.map(path=>`<path d="${path}"/>`).join('')}</g>${dots}</svg><figcaption><span><i class="kit-dot"></i>우리 선발 · 공격 방향 →</span><span>회색: 상대 배치 예시</span><small>${caption} 선수 배치는 전술을 설명하는 개념도입니다.</small></figcaption></figure>`;
}
function tacticsBoardMarkup(d,previewTactic,open=true){
 if(!d.valid)return '';
 const selected=d.previews.find(p=>p.tactic===previewTactic)||d.previews.find(p=>p.tactic===d.context.tactic),label=d.previews.find(p=>p.tactic===d.context.tactic).label,opponent=S.club(d.context.opponentId),period={prep:'킥오프 전',half:'하프타임',late:'65분 작전 시간'}[d.context.phase]||d.context.minute+'분 작전 타임',heading='전술 분석';
 const cards=d.previews.map(p=>`<button type="button" class="tactics-choice ${p.tactic===d.recommendation.tactic?'coach-choice':''}" data-tactics-preview="${p.tactic}" aria-pressed="${p.tactic===selected.tactic}" aria-label="${p.label} 미리보기" aria-describedby="tactics-description-${p.tactic}"><span class="tactics-choice-title">${p.label}<small>${p.tactic===d.context.tactic?'현재 지시':p.tactic===d.recommendation.tactic?'코치 제안':'미리보기'}</small></span><span class="tactics-chance-values"><b>${tacticsNumber(p.expectedChances.ours)}</b><i>:</i><b>${tacticsNumber(p.expectedChances.opponent)}</b></span><span class="tactics-choice-caption">우리 : 상대 찬스 지표</span><span class="tactics-cost">선발 평균 체력 소모 <strong>−${tacticsNumber(p.averageCost)}</strong></span><span id="tactics-description-${p.tactic}" class="sr-only">${p.tactic===d.context.tactic?'현재 경기 지시. ':''}${p.tactic===d.recommendation.tactic?'코치가 제안한 전술. ':''}다음 ${d.segment.minutes}분의 현재 체력 기준 찬스 지표: 우리 ${tacticsNumber(p.expectedChances.ours)}, 상대 ${tacticsNumber(p.expectedChances.opponent)}. 선발 평균 체력 소모 ${tacticsNumber(p.averageCost)}.</span></button>`).join('');
 const comparisons=d.current.comparisons.map(p=>`<div class="tactics-comparison"><div><span>${p.label}</span><b>${tacticsNumber(p.ours)} <i>/</i> <em>${tacticsNumber(p.opponent)}</em></b></div><div class="tactics-bars" aria-hidden="true"><i style="width:${Math.min(100,p.ours)}%"></i><i style="width:${Math.min(100,p.opponent)}%"></i></div></div>`).join('');
 const energyAfter=selected.energy.reduce((sum,p)=>sum+p.after,0)/11,tired=[...d.lineup].sort((a,b)=>a.energy-b.energy).slice(0,3),effect={balanced:'공격과 수비의 균형을 유지합니다.',press:'균형 대비 우리 찬스 비율 +18%, 상대 +13%. 90분 기준 추가 체력 소모 8입니다.',counter:'균형 대비 우리 찬스 비율 −10%, 상대 −8%. 빠른 공격진에는 역습 보너스가 붙습니다.'}[selected.tactic];
 return `<details class="tactics-board" ${open?'open':''}><summary><span><span class="eyebrow">TACTICS ROOM / ${period}</span><strong>${heading}</strong></span><span class="tactics-summary-meta">현재 ${escapeText(label)}<small>선발·상대 비교와 전술 미리보기</small></span></summary><div class="tactics-board-body"><div class="tactics-coach"><span class="tactics-coach-badge">코치 제안<br><b>${escapeText(d.recommendation.label)}</b></span><p>${escapeText(d.recommendation.reason)}</p></div><div class="tactics-board-top">${tacticsDiagram(d,selected.tactic)}<div class="tactics-matchups"><div class="tactics-matchups-heading"><h3>선발과 상대 비교</h3><span>우리 / ${escapeText(opponent.short)}</span></div>${comparisons}<p>컨디션을 반영한 같은 항목 비교 · 속도는 우리 공격진과 상대 수비 속도</p></div></div><div class="tactics-window-label"><h3>다음 ${d.segment.minutes}분 전술 비교</h3><span>현재 체력 기준 찬스 지표</span></div><div class="tactics-choice-grid" role="group" aria-label="전술 미리보기">${cards}</div><div class="tactics-effect" aria-live="polite"><div><span class="eyebrow">PREVIEW / ${escapeText(selected.label)}</span><p>${effect}</p><span>슈팅 1회 득점 확률 <b>우리 ${tacticsNumber(selected.goalChance.ours*100)}%</b> · 상대 ${tacticsNumber(selected.goalChance.opponent*100)}%${selected.tactic==='counter'?' · 공격 지표 보너스 +'+tacticsNumber(selected.paceBonus):''}</span><span>구간 끝 선발 평균 체력 <b>${tacticsNumber(d.condition.averageEnergy)} → ${tacticsNumber(energyAfter)}</b></span></div><div class="tactics-apply-area"><button type="button" class="secondary" data-tactics-apply="${selected.tactic}" ${selected.tactic===d.context.tactic?'disabled':''}>${selected.tactic===d.context.tactic?'이미 적용된 경기 지시':'이 전술로 지시 변경'}</button><small>지시만 바뀝니다. 경기 시작·이어가기는 아래 버튼에서 결정하세요.</small></div></div><div class="tactics-energy-check"><div><h3>체력이 낮은 선발</h3><span>선발 중 체력이 낮은 3명 · 선수 카드로 확인</span></div><div class="tactics-tired-list">${tired.map(p=>`<button type="button" class="tactics-tired-player" data-player-detail="${escapeText(p.identity)}" aria-label="${escapeText(p.name)} 선수 상세"><span>${Portraits.html(p)}</span><span><strong>${escapeText(p.name)}</strong><small>${p.pos} · 체력 ${tacticsNumber(p.energy)}</small></span></button>`).join('')}</div></div><p class="tactics-assumption">${escapeText(d.assumption)} 체력 소모는 현재 선발이 교체 없이 구간을 뛴다는 기준입니다.</p></div></details>`;
}
function readTacticsPlan(){return TacticsBoard.read(season,{coachPause65:typeof playbackPrefs==='undefined'?true:playbackPrefs.coachPause65});}
function renderTacticsBoard(){
 const host=document.getElementById('tactics-board');if(!host)return;
 if(!state){host.hidden=true;host.innerHTML='';tacticsBoardFingerprint=null;tacticsPreviewContext=null;return;}
 if(typeof view!=='undefined'&&view!=='match'||typeof matchdayTab!=='undefined'&&matchdayTab!=='analysis')return;
 const previous=host.querySelector('details');if(previous)tacticsBoardOpen=previous.open;
 const d=readTacticsPlan();host.hidden=!d.valid;
 if(!d.valid){host.innerHTML='';tacticsBoardFingerprint=null;tacticsPreviewContext=null;return;}
 const context=JSON.stringify([d.context.seed,d.context.year,d.context.competition,d.context.round,d.context.stage,d.context.phase,d.context.minute,d.context.paused,d.segment.end,d.context.formation,d.context.tactic,d.lineup.map(p=>p.identity)]);
 if(context!==tacticsPreviewContext){tacticsPreview=d.context.tactic;tacticsPreviewContext=context;}
 tacticsBoardFingerprint=d.fingerprint;host.innerHTML=tacticsBoardMarkup(d,tacticsPreview,tacticsBoardOpen);
}
function previewTactics(tactic){
 if(!['balanced','press','counter'].includes(tactic))return;
 const d=readTacticsPlan();if(!d.valid)return;
 const host=document.getElementById('tactics-board'),details=host.querySelector('details');if(details)tacticsBoardOpen=details.open;
 tacticsPreview=tactic;tacticsBoardFingerprint=d.fingerprint;
 host.innerHTML=tacticsBoardMarkup(d,tactic,tacticsBoardOpen);host.querySelector(`[data-tactics-preview="${tactic}"]`)?.focus({preventScroll:true});
}
function applyTacticsPreview(tactic){
 const expected=tacticsBoardFingerprint;
 action(()=>{const d=readTacticsPlan();if(!d.valid||d.fingerprint!==expected||tactic!==tacticsPreview||!d.previews.some(p=>p.tactic===tactic))throw Error('선발이나 경기 상황이 바뀌었습니다. 전술 보드를 다시 확인하세요.');F.setTactic(state,tactic);});
 document.getElementById('tactics-board')?.querySelector(`[data-tactics-preview="${tactic}"]`)?.focus({preventScroll:true});
}
document.getElementById('tactics-board')?.addEventListener('click',event=>{const preview=event.target.closest('[data-tactics-preview]'),apply=event.target.closest('[data-tactics-apply]');if(preview)previewTactics(preview.dataset.tacticsPreview);else if(apply&&!apply.disabled)applyTacticsPreview(apply.dataset.tacticsApply);});
